def editor_note(line):
    if not line.strip(): return 'Blank line separating document or script sections.'
    for prefix,note in EDITOR_NOTES:
        if line.startswith(prefix): return note
    raise ValueError(f'Editor line needs a reviewed explanation: {line[:100]}')
